import{_ as l,a0 as d,w as p,s as r,I as n,x as i,a1 as t,A as a,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"可以運行在 Windows 10 中的最實用的 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"可以運行在 Windows 10 中的最實用的 Linux 命令 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"可以運行在 Windows 10 中的最實用的 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"可以運行在 Windows 10 中的最實用的 Linux 命令 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180306 Most Useful Linux Commands You Can Run in Windows 10","title":"可以運行在 Windows 10 中的最實用的 Linux 命令","tag":"201803","desc":""},"relativePath":"201803/20180306 Most Useful Linux Commands You Can Run in Windows 10.md","filePath":"[post].md"}'),u={name:"201803/20180306 Most Useful Linux Commands You Can Run in Windows 10.md"};function g(h,s,k,b,c,m){const e=d("Link");return p(),r("div",null,[s[28]||(s[28]=n("h1",{id:"可以運行在-windows-10-中的最實用的-linux-命令",tabindex:"-1"},[i("可以運行在 Windows 10 中的最實用的 Linux 命令 "),n("a",{class:"header-anchor",href:"#可以運行在-windows-10-中的最實用的-linux-命令","aria-label":"Permalink to “可以運行在 Windows 10 中的最實用的 Linux 命令”"},"​")],-1)),s[29]||(s[29]=n("p",null,[n("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/wsl-commands.png?itok=91oEXdO8",alt:""})],-1)),n("p",null,[s[1]||(s[1]=i("在本系列早先的文章中，我們討論了關於如何在 ",-1)),t(e,{href:"https://www.linux.com/blog/learn/2018/2/how-get-started-using-wsl-windows-10"},{default:a(()=>[...s[0]||(s[0]=[i("Windows 10 上開啓 WSL 之旅",-1)])]),_:1}),s[2]||(s[2]=i(" 的內容。作為本系列的最後一篇文章，我們準備探討一些能在 Windows 10 上廣泛使用的 Linux 命令。",-1))]),s[30]||(s[30]=o(`<p>話題深入之前，請先讓我們明確本教程所適用的人羣。本文適用於使用 Windows 10 系統，但是又想在 Azure、AWS 或是私有云平台上學習 Linux 的初級開發者。換句話説，就是為了幫助初次接觸 Linux 系統的 Windows 10 用户。</p><p>您的工作任務決定了您所需要的命令，而我的需求可能和您的不一樣。本文旨在幫助您在 Windwos 10 上舒服的使用 Linux。不過請牢記，WSL 並不提供硬件訪問的功能，比如聲卡、GPU，至少官方是這麼描述的。但是這可能並不能阻止 Linux 用户的折騰精神。很多用户不僅完成了硬件訪問，甚至已經在 Windows 10 上安裝上了 Linux 桌面程序。但是本文並不會涉及這些內容，我們可能會討論這些，但不是現在。</p><p>下面是我們需要着手的任務。</p><h3 id="如何讓您的-linux-系統保持到最新的版本" tabindex="-1">如何讓您的 Linux 系統保持到最新的版本 <a class="header-anchor" href="#如何讓您的-linux-系統保持到最新的版本" aria-label="Permalink to “如何讓您的 Linux 系統保持到最新的版本”">​</a></h3><p>因為 Linux 運行在了 Windows 系統中，所以您將被剝奪 Linux 系統所提供的所有安全特性。另外，如果不及時給 Linux 系統打補丁，你的 Windows 設備將被迫暴露在外界威脅中，所以還請保持您的 Linux 為最新版本。</p><p>WSL 官方支持 openSUSE/SUSE Linux Enterprise 和 Ubuntu。您也可以安裝其他發行版，但是我只需要它們當中的二者之一就可以完成我的所有工作，畢竟，我只需要訪問一些 Linux 基礎程序。</p><p><strong>更新 openSUSE Leap：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zypper up</span></span></code></pre></div><p>如果您想升級系統，您可以運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zypper dup</span></span></code></pre></div><p><strong>更新 Ubuntu：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get dist-upgrade</span></span></code></pre></div><p>這樣你就安全了，由於 Linux 系統的更新是漸進式的，所以更新系統成為了我的日常。不像 Windows 10 的更新通常需要重啓系統，而 Linux 不同，一般只有 KB 或是 MB 級的更新，無需重啓。</p><h3 id="管理文件目錄" tabindex="-1">管理文件目錄 <a class="header-anchor" href="#管理文件目錄" aria-label="Permalink to “管理文件目錄”">​</a></h3><p>系統更新之後，我們來看看一些或普通或不太普通的任務。</p><p>系統更新之外的第二重要的任務是使用 Linux 管理本地和遠程文件。我承認我更青睞圖形界面程序，但是終端能提供更可靠、更有價值的服務。要不你使用資源管理器移動 1 TB 的文件試試？我通常使用 <code>rsync</code> 命令來移動大量文件。如果中斷任務，<code>rsync</code> 可以在上次停止的位置繼續工作。</p><p>雖然您可能更習慣使用 <code>cp</code> 或是 <code>mv</code> 命令複製、移動文件，但是我還是喜歡靈活的 <code>rsync</code> 命令，瞭解 <code>rsync</code> 對遠程文件傳輸也有幫助。使用 <code>rsync</code> 大半為了完成下面三個任務：</p><p><strong>使用 rsync 複製整個目錄：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -avzP /source-directory /destination directory</span></span></code></pre></div><p><strong>使用 rsync 移動文件：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync --remove-source-files -avzP /source-directory /destination-directory</span></span></code></pre></div><p>在成功複製目標目錄之後，此命令將刪除源文件。</p><p><strong>使用 rsync 同步文件：</strong></p><p>我的文件可能在多處存儲。但是，我只會在主要位置中增加或是刪除。如果不使用專業的軟件，同步文件可能會給用户帶來挑戰，而 <code>rsync</code> 剛好可以簡化這個過程。這個命令可以讓兩個目錄文件內容同步。不過要注意，這是一個單向同步，即從源位置同步到目標位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync --delete -avzP /source-directory /destination-directory</span></span></code></pre></div><p>如果源目錄中沒有找到文件，上述命令將刪除目標目錄中的文件。換言之，它創建了源目錄的一個鏡像。</p><h3 id="文件自動備份" tabindex="-1">文件自動備份 <a class="header-anchor" href="#文件自動備份" aria-label="Permalink to “文件自動備份”">​</a></h3><p>保持文件備份是一項乏味的工作。為了保持我的設備的完全同步，我運行了一個 cron 作業在夜間保持我的所有目錄同步。不過我會留一個外部驅動器，基本上每週我都會手動同步一次。由於可能刪掉我不想刪除的文件，所以我並沒有使用 <code>--delete</code> 選項。我會根據情況手動決定是否使用這個選項。</p><p><strong>創建 cron 作業，打開 crontab：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>crontab -e</span></span></code></pre></div><p>移動大文件時，我會選擇在系統空閒的深夜執行該命令。此命令將在每天早上 1 點運行，您大概可以這樣修改它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 0 1 * * * rsync -avzP /source-directory /destination-directory</span></span></code></pre></div><p>這是使用 crontab 的定時作業的命令結構：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># m h dom mon dow command</span></span></code></pre></div><p>在此，<code>m</code> = 分鐘，<code>h</code> = 小時，<code>dom</code> = 本月的某天，<code>mon</code> = 月，<code>dow</code> = 本週的某天。</p>`,35)),n("p",null,[s[4]||(s[4]=i("我們將在每天早上 1 點運行這條命令。您可以選擇 ",-1)),s[5]||(s[5]=n("code",null,"dow",-1)),s[6]||(s[6]=i(" 或是 ",-1)),s[7]||(s[7]=n("code",null,"dom",-1)),s[8]||(s[8]=i("（比如，每月 5 號）等。您可以在 ",-1)),t(e,{href:"http://www.adminschoice.com/crontab-quick-reference"},{default:a(()=>[...s[3]||(s[3]=[i("這裏",-1)])]),_:1}),s[9]||(s[9]=i(" 閲讀更多相關內容。",-1))]),s[31]||(s[31]=o('<h3 id="管理遠程服務器" tabindex="-1">管理遠程服務器 <a class="header-anchor" href="#管理遠程服務器" aria-label="Permalink to “管理遠程服務器”">​</a></h3><p>在 Windows 系統上使用 WSL 的優勢之一就是能方便管理雲上的 Linux 服務器，WSL 能提供原生的 Linux 工具給您。首先，您需要使用 <code>ssh</code> 命令登錄遠程 Linux 服務器。</p><p>比如，我的服務器 ip 是 192.168.0.112；端口為 2018（不是默認的 22 端口）；Linux 用户名是 swapnil，密碼是 “就不告訴你”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -p2018 swapnil@192.168.0.112</span></span></code></pre></div><p>它會向您詢問用户密碼，然後您就可以登錄到 Linux 服務器了。現在您可以在 Linux 服務器上執行任意您想執行的所有操作了。不需使用 PuTTY 程序了。</p><p>使用 <code>rsync</code> ，您可以很輕易的在本地機器和遠程機器之間傳輸文件。源目錄還是目標目錄取決於您是上傳文件到服務器，還是下載文件到本地目錄，您可以使用 <code>username@IP-address-of-server:/path-of-directory</code> 來指定目錄。</p><p>如果我想複製一些文本內容到服務器的 home 目錄，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -avzP /source-directory-on-local-machine ‘ssh -p2018’ swapnil@192.168.0.112:/home/swapnil/Documents/</span></span></code></pre></div><p>這將會複製這些文件到遠程服務器中 <code>Documents</code> 目錄。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本教程主要是為了證明您可以在 Windows 10 系統上通過 WSL 完成 Linux 方面的很大一部分的任務。通常來説，它提高了生產效率。現在，Linux 的世界已經向 Windwos 10 系統張開懷抱了，盡情探索吧。如果您有任何疑問，或是想了解 WSL 涉及到的其他層面，歡迎在下方的評論區分享您的想法。</p>',11)),n("p",null,[s[12]||(s[12]=i("在 ",-1)),t(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/administering-linux-on-azure"},{default:a(()=>[...s[10]||(s[10]=[i("Administering Linux on Azure (LFS205)",-1)])]),_:1}),s[13]||(s[13]=i(" 課程中瞭解更多，可以在 ",-1)),t(e,{href:"http://bit.ly/2FpFtPg"},{default:a(()=>[...s[11]||(s[11]=[i("這裏",-1)])]),_:1}),s[14]||(s[14]=i(" 註冊。",-1))]),s[32]||(s[32]=n("hr",null,null,-1)),n("p",null,[s[16]||(s[16]=i("via: ",-1)),t(e,{href:"https://www.linux.com/blog/learn/2018/3/most-useful-linux-commands-you-can-run-windows-10"},{default:a(()=>[...s[15]||(s[15]=[i("https://www.linux.com/blog/learn/2018/3/most-useful-linux-commands-you-can-run-windows-10",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=i("作者：",-1)),t(e,{href:"https://www.linux.com/users/arnieswap"},{default:a(()=>[...s[17]||(s[17]=[i("SAPNIL BHARTIYA",-1)])]),_:1}),s[21]||(s[21]=i(" 譯者：",-1)),t(e,{href:"https://github.com/CYLeft"},{default:a(()=>[...s[18]||(s[18]=[i("CYLeft",-1)])]),_:1}),s[22]||(s[22]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[19]||(s[19]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[25]||(s[25]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[23]||(s[23]=[i("LCTT",-1)])]),_:1}),s[26]||(s[26]=i(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[24]||(s[24]=[i("Linux中國",-1)])]),_:1}),s[27]||(s[27]=i(" 榮譽推出",-1))])])}const w=l(u,[["render",g]]);export{y as __pageData,w as default};
